import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

avg_pool2d_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAGuard.h>

__global__ void avg_pool2d_kernel(
    const float* input,
    float* output,
    int batch_size,
    int channels,
    int in_h,
    int in_w,
    int out_h,
    int out_w,
    int kernel_size,
    int stride,
    int padding
) {
    int index = blockIdx.x * blockDim.x + threadIdx.x;
    int total_elements = batch_size * channels * out_h * out_w;
    if (index >= total_elements) return;

    int n = index / (channels * out_h * out_w);
    int c = (index / (out_h * out_w)) % channels;
    int h_out = (index / out_w) % out_h;
    int w_out = index % out_w;

    int h_start = h_out * stride - padding;
    int w_start = w_out * stride - padding;
    int h_end = h_start + kernel_size;
    int w_end = w_start + kernel_size;

    h_start = max(h_start, 0);
    w_start = max(w_start, 0);
    h_end = min(h_end, in_h);
    w_end = min(w_end, in_w);

    float sum = 0.0f;
    int count = 0;
    for (int h = h_start; h < h_end; ++h) {
        for (int w = w_start; w < w_end; ++w) {
            int input_idx = n * channels * in_h * in_w + c * in_h * in_w + h * in_w + w;
            sum += input[input_idx];
            count += 1;
        }
    }
    output[index] = count > 0 ? sum / count : 0.0f;
}

torch::Tensor avg_pool2d_cuda(torch::Tensor x, int kernel_size, int stride, int padding) {
    at::cuda::CUDAGuard guard(x.device());
    int batch_size = x.size(0);
    int channels = x.size(1);
    int in_h = x.size(2);
    int in_w = x.size(3);

    int out_h = (in_h + 2 * padding - kernel_size) / stride + 1;
    int out_w = (in_w + 2 * padding - kernel_size) / stride + 1;

    auto output = torch::zeros({batch_size, channels, out_h, out_w}, x.options());

    int total_elements = batch_size * channels * out_h * out_w;
    const int block_size = 256;
    int num_blocks = (total_elements + block_size - 1) / block_size;

    avg_pool2d_kernel<<<num_blocks, block_size>>>(
        x.data_ptr<float>(),
        output.data_ptr<float>(),
        batch_size,
        channels,
        in_h,
        in_w,
        out_h,
        out_w,
        kernel_size,
        stride,
        padding
    );

    return output;
}
"""

avg_pool2d_cpp_source = "torch::Tensor avg_pool2d_cuda(torch::Tensor x, int kernel_size, int stride, int padding);"

avg_pool2d = load_inline(
    name='avg_pool2d',
    cpp_sources=avg_pool2d_cpp_source,
    cuda_sources=avg_pool2d_source,
    functions=['avg_pool2d_cuda'],
    verbose=True,
    extra_cflags=['-O2'],
    extra_ldflags=[],
)

class ModelNew(nn.Module):
    def __init__(self, kernel_size: int, stride: int = None, padding: int = 0):
        super().__init__()
        self.kernel_size = kernel_size
        self.stride = stride if stride is not None else kernel_size
        self.padding = padding

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return avg_pool2d.avg_pool2d_cuda(x, self.kernel_size, self.stride, self.padding)
